/** Decode a sample scene's base64 to the raw .m3p bytes. */
export function decodeSampleScene(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
